export const MAP_LAYOUT = arena(ARENA_VARIANTS.grassland);

/** @type {Record<string, string[]>} — every authored board, built once. */
export const MAPS = Object.fromEntries(
  Object.entries(ARENA_VARIANTS).map(([id, spec]) => [id, arena(spec)])
);

/**
 * Per-tile biome overlay for the endless battlefield — the only map that
 * changes biome underfoot. The grid is generated from the arena size so it can
 * never drift out of step with the layout again.
 *
 *   i  ice       d  desert      v  volcanic      c  crystal
 *
 * The bands follow the arena grammar instead of a diagonal: snowfield under the
 * portal, dunes across the enemy's corridor, and the caldera from the water down
 * to the rock. Three bands, not four: the crystal strip that used to sit under
 * the keep turned the bottom of the board lilac and made the bastion look like
 * it had been dropped on a different map. The river is the seam the player
 * already reads, so the warm half starts there.
 */
function endlessBiomeGrid() {
  const rows = [];
  for (let r = 0; r < ARENA.rows; r += 1) {
    // Bands are cut on the arena's own rows, so moving the river or the bastion
    // re-cuts the biomes with it: snow over the enemy half, dunes across the
    // water, caldera on our bank, crystal under the dais.
    // The water row itself stays desert-themed: the divider must read as water
    // on every map, and the volcanic tile set paints standing liquid as lava.
    const band = r < ARENA.buildRow ? 'i' : r < ARENA.baseRow - 1 ? 'd' : 'v';
    rows.push(band.repeat(ARENA.cols));
  }
  return rows;
}

export const MAP_BIOMES = {
  volcanic: endlessBiomeGrid(),
};

/** Biome letter -> campaign theme id (each one owns a generated tile set). */
export const BIOME_THEME = Object.freeze({
  i: 'ice',
  d: 'desert',
  v: 'volcanic',
  c: 'crystal',
});

export const TILE = {
  GRASS: 'grass',
  ROAD: 'road',
  SPAWN: 'spawn',
  /** A sky gate: where flyers enter. Not walkable — no ground lane starts here. */
  AIR: 'air',
  BASE: 'base',
  ROCK: 'rock',
  WATER: 'water',
};

const CHAR_TO_TILE = {
  '.': TILE.GRASS,
  '#': TILE.ROAD,
  S: TILE.SPAWN,
  a: TILE.AIR,
  B: TILE.BASE,
  x: TILE.ROCK,
  '~': TILE.WATER,
};

/**
 * Convert the string layout into a 2D array of tile types and locate the gates.
 *
 * A board has **one bastion** and **one or more ground portals**; a stage that
 * attacks from several directions lists three, and every one of them has to
 * reach the keep (`PathfindingSystem.computeLanes` proves it on load). Sky
 * gates are collected separately because they are not walkable — they are the
 * weather vane the air routes start from, not a spawn point for the horde.
 *
 * Throws a descriptive error if the layout is malformed, so a broken map is
 * caught before gameplay starts.
 */
export function parseMap(layout = MAP_LAYOUT) {
  const rows = layout.length;
  const cols = layout[0]?.length ?? 0;
  const tiles = [];
  const spawns = [];
  const airGates = [];
  let base = null;

  for (let r = 0; r < rows; r++) {
    if (layout[r].length !== cols) {
      throw new Error(`Map row ${r} has ${layout[r].length} columns, expected ${cols}`);
    }
    const row = [];
    for (let c = 0; c < cols; c++) {
      const ch = layout[r][c];
      const type = CHAR_TO_TILE[ch];
      if (!type) throw new Error(`Unknown map character '${ch}' at row ${r}, col ${c}`);
      if (type === TILE.SPAWN) spawns.push({ row: r, col: c });
      if (type === TILE.AIR) airGates.push({ row: r, col: c });
      if (type === TILE.BASE) {
        if (base) throw new Error('Map has more than one base');
        base = { row: r, col: c };
      }
      row.push(type);
    }
    tiles.push(row);
  }
  if (!spawns.length) throw new Error('Map has no spawn (S)');
  if (!base) throw new Error('Map has no base (B)');

  // Ponds are scenery now, so a "river row" is a diagnostic rather than a rule:
  // a row that is mostly water still gets reported (the flow shader asks for
  // it), but nothing in the build or lane rules depends on it any more.
  let riverRow = null;
  let widest = 0;
  for (let r = 0; r < rows; r += 1) {
    const water = tiles[r].filter((tile) => tile === TILE.WATER).length;
    if (water > widest) {
      widest = water;
      riverRow = r;
    }
  }
  if (widest < Math.max(3, Math.floor(cols / 3))) riverRow = null;

  return {
    rows,
    cols,
    tiles,
    spawns,
    /** First portal — kept for callers that only need one (minimaps, hints). */
    spawn: spawns[0],
    airGates,
    base,
    riverRow,
    /** First row of the free-build field, straight from the grammar. */
    buildRow: ARENA.buildRow,
  };
}

/**
 * Resolve a map id to its layout, falling back to the original battlefield so a
 * typo in a level definition can never crash the scene.
 */
export function getMapLayout(mapId) {
  return MAPS[mapId] || MAP_LAYOUT;
}

/**
 * Biome grid for a map id, or null when the battlefield is single-biome.
 *
 * Returns `[[themeId, …], …]` so the renderer can ask "which tile set owns this
 * square?" without knowing anything about the letters. A malformed grid is
 * ignored rather than thrown: a texture lookup falling back to the level theme
 * is a cosmetic problem, a crash mid-wave is not.
 */
export function getMapBiomes(mapId) {
  const grid = MAP_BIOMES[mapId];
  if (!grid) return null;
  const layout = getMapLayout(mapId);
  if (grid.length !== layout.length) return null;
  const rows = [];
  for (let r = 0; r < grid.length; r++) {
    if (grid[r].length !== layout[r].length) return null;
    const row = [];
    for (let c = 0; c < grid[r].length; c++) {
      row.push(BIOME_THEME[grid[r][c]] || null);
    }
    rows.push(row);
  }
  return rows;
}

/** Road-like tiles that enemies can walk on (graph nodes). */
export function isWalkableTile(type) {
  return type === TILE.ROAD || type === TILE.SPAWN || type === TILE.BASE;
}

/** Tiles where towers may be built. */
export function isBuildableTile(type) {
  return type === TILE.GRASS;
}
